def _srv_post(url, **kw):
    """서버 POST를 세션으로. 시험이 requests.post를 바꿔 끼웠으면 그것을 쓴다(종전 시험 그대로)."""
    if getattr(_rq_mod.post, "__module__", "") != "requests.api":
        return _rq_mod.post(url, **kw)
    return _SRV_HTTP.post(url, **kw)


_CAFF = None                  # 맥 caffeinate 프로세스(라이브 동안)


def _keep_awake(on: bool) -> bool:
    """라이브 무장 동안 시스템 유휴 절전 막기(대표 2026-10-20: 회원 기기가 하루 10~28번 15분 넘게 응답이 없다가 돌아오고, 마감 3분 뒤에
    신호를 받아 '늦게 도착'으로 건너뜀). 윈도 = SetThreadExecutionState(ES_CONTINUOUS | ES_SYSTEM_REQUIRED) - 화면은 꺼져도 되고 시스템
    유휴 절전만 막는다. 이 상태는 부른 스레드에 붙으므로 **화면 줄에서만** 부른다(앱이 끝나면 저절로 풀린다). 맥 = caffeinate -i -w <앱 pid>.
    덮개 닫기, 손으로 누른 절전, 배터리 정책은 막지 못한다. 반환 = 요청을 넣었는지."""
    global _CAFF
    try:
        if sys.platform.startswith("win"):
            import ctypes
            _ES_CONTINUOUS, _ES_SYSTEM_REQUIRED = 0x80000000, 0x00000001
            return bool(ctypes.windll.kernel32.SetThreadExecutionState(_ES_CONTINUOUS | (_ES_SYSTEM_REQUIRED if on else 0)))
        if sys.platform == "darwin":
            if on and _CAFF is None:
                _CAFF = subprocess.Popen(["caffeinate", "-i", "-w", str(os.getpid())],
                                         stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
                return True
            if not on and _CAFF is not None:
                _CAFF.terminate()
                _CAFF = None
                return True
    except Exception:
        pass
    return False


def _srv_get(url, **kw):
    if getattr(_rq_mod.get, "__module__", "") != "requests.api":
        return _rq_mod.get(url, **kw)
    return _SRV_HTTP.get(url, **kw)

# ── 앱 로그 파일 영속화(대표 2026-07-15): 화면 로그를 일자별 파일에도 기록(타임스탬프 부여).
#    앱을 닫아도 수신·체결 지연 기록이 남아 사후 감사 가능. 30일 지난 파일은 시작 시 정리. ──
LOG_DIR = os.path.join(APP_DIR, "logs")
_LOG_LOCK = threading.Lock()


def _log_to_file(msg):
    try:
        os.makedirs(LOG_DIR, exist_ok=True)
        now = _dt.datetime.now()
        ts = now.strftime("%H:%M:%S")
        path = os.path.join(LOG_DIR, f"eq-{now:%Y%m%d}.log")
        with _LOG_LOCK, open(path, "a", encoding="utf-8") as f:
            for ln in str(msg).split("\n"):
                f.write(f"[{ts}] {ln}\n")
    except Exception:
        pass                     # 로그 실패가 매매를 막으면 안 됨


def _prune_logs(days: int = 30):
    try:
        import time as _tm
        cut = _tm.time() - days * 86400
        for fn in os.listdir(LOG_DIR):
            p = os.path.join(LOG_DIR, fn)
            if fn.startswith("eq-") and fn.endswith(".log") and os.path.getmtime(p) < cut:
                os.remove(p)
    except Exception:
        pass


_prune_logs()

