_POS_LOCK = threading.RLock()        # 최근 진입 기록 사전(메모리)만 - 이 안에서 파일, 네트워크를 쓰지 않는다
_POS_BUSY_LOCK = threading.Lock()    # 진입 중 수 세기만
_POS_FILE_LOCK = threading.Lock()    # .pos_today.json 쓰기(원장 잠금 _JSON_LOCK과 따로 - 진입 스레드의 원장 기록을 기다리게 하지 않는다)


def _pos_clock() -> float:
    """보유 줄이 쓰는 지금 시각(epoch). 시험이 바꿔 끼운다."""
    import time as _t
    return _t.time()


def _in_tz(tzname, u):
    """UTC 시각 u(tz-aware) → tzname 시각. _now_in과 같은 규칙(UTC 내장, ET는 ZoneInfo가 없으면 산술)."""
    if tzname == "UTC":
        return u
    if ZoneInfo is not None:
        try:
            return u.astimezone(ZoneInfo(tzname))
        except Exception:
            pass
    if "New_York" in tzname:
        off = _us_eastern_offset(u)
        return (u + _dt.timedelta(hours=off)).replace(tzinfo=_dt.timezone(_dt.timedelta(hours=off)))
    return u


def _pos_bar_epochs(asset, now, table):
    """table(_ASSET_ENTRIES, _ASSET_EXITS)의 이 자산 시각 가운데 now 앞뒤 하루 안의 것 [(epoch, tz, hour, 그 tz 날짜 'YYYY-MM-DD')]."""
    out = []
    u = _dt.datetime.fromtimestamp(float(now), _dt.timezone.utc)
    for tzname, hour in table.get(str(asset), ()):
        loc = _in_tz(tzname, u)
        for dd in (-1, 0, 1):
            d = (loc + _dt.timedelta(days=dd)).replace(hour=int(hour), minute=0, second=0, microsecond=0)
            out.append((d.timestamp(), tzname, int(hour), d.strftime("%Y-%m-%d")))
    return out


def _pos_entry_quiet(assets, now) -> bool:
    """진입 봉 마감(요일 무시 - 쉬어서 손해 볼 일이 없다) _POS_QUIET_S초 전부터 _POS_AFTER_BAR_S초 뒤까지면 True. 계산이 실패하면 True."""
    try:
        now = float(now)
        for a in assets or ():
            for e, _tz, _h, _d in _pos_bar_epochs(a, now, _ASSET_ENTRIES):
                if -_POS_QUIET_S <= now - e < _POS_AFTER_BAR_S:
                    return True
        return False
    except Exception:
        return True


def _pos_next_entry_after(asset, t):
    """t(epoch) 뒤 이 자산의 다음 진입 시각(epoch) - _next_entry_dt와 같은 요일 규칙(NQ, GC 평일, BTC 일요일 UTC만). 모르면 None."""
    best = None
    try:
        u = _dt.datetime.fromtimestamp(float(t), _dt.timezone.utc)
        for tzname, hour in _ASSET_ENTRIES.get(str(asset), []):
            n = _in_tz(tzname, u)
            d = n.replace(hour=int(hour), minute=0, second=0, microsecond=0)
            if d <= n:
                d += _dt.timedelta(days=1)
            _days = _ENTRY_DAYS.get(str(asset)) or tuple(range(7))
            for _ in range(8):
                if d.weekday() in _days:
                    break
                d += _dt.timedelta(days=1)
            e = d.timestamp()
            if best is None or e < best:
                best = e
    except Exception:
        return None
    return best


def _pos_rec_until(asset, ts0) -> float:
    """최근 진입 기록이 사는 끝 = 첫 체결(+_POS_REC_GRACE_S) 뒤 이 자산의 다음 진입 시각. 계산이 실패하면 첫 체결 8일 뒤."""
    e = _pos_next_entry_after(asset, float(ts0) + _POS_REC_GRACE_S)
    return float(e) if e is not None else float(ts0) + 8 * 86400


def _pos_root(sym) -> str:
    """종목 이름 → 화면에 쓰는 뿌리('CON.F.US.ENQ.Z26' → 'NQ', 'MNQ 12-26' → 'MNQ', 'BTCUSDT' → 'BTC')."""
    try:
        from eqexec.asset_scope import sym_root
        r = sym_root(sym) or str(sym or "").upper()
    except Exception:
        r = str(sym or "").upper()
    return _POS_ROOT_ALIAS.get(r, r)


def _pos_num(v):
    """숫자(유한) 또는 None - 빈 문자열, None, NaN, 무한대는 None."""
    try:
        if v is None or isinstance(v, bool) or (isinstance(v, str) and not v.strip()):
            return None
        f = float(v)
        return f if f == f and f not in (float("inf"), float("-inf")) else None
    except (TypeError, ValueError):
        return None


def _pos_legs_txt(asset, legs, ko) -> str:
    """{'NQ': 1, 'MNQ': 3} → 'NQ 1 + MNQ 3계약'(EN 'NQ 1 + MNQ 3'). BTC는 코인 수량('BTC 0.012', 계약 없음)."""
    items = []
    for r, q in (legs or {}).items():
        q = _pos_num(q)
        if q:
            items.append((str(r), abs(q)))
    if not items:
        return ""
    items.sort(key=lambda x: (_POS_ROOT_ORDER.index(x[0]) if x[0] in _POS_ROOT_ORDER else 99, x[0]))
    coin = str(asset) == "BTC"
    parts = [f"{r} " + (f"{q:.4f}".rstrip("0").rstrip(".") if coin else str(int(round(q)))) for r, q in items]
    return " + ".join(parts) + ("계약" if ko and not coin else "")


def _pos_usd(v) -> str:
    """평가 손익 → '+$812', '-$45', '$0', 모르면 '-'."""
    v = _pos_num(v)
    if v is None:
        return "-"
    n = int(round(v))
    return f"+${n:,}" if n > 0 else (f"-${-n:,}" if n < 0 else "$0")


def _pos_age_txt(age, ko) -> str:
    """낡은 값 표시 ' (3분 전 기준)' / ' (as of 3 min ago)'."""
    m = max(1, int(float(age) // 60))
    if m >= 120:
        h = m // 60
        return f" ({h}시간 전 기준)" if ko else f" (as of {h} h ago)"
    return f" ({m}분 전 기준)" if ko else f" (as of {m} min ago)"


def _pos_line_hold(asset, legs, n_acct, pnl, ko) -> str:
    lg = _pos_legs_txt(asset, legs, ko)
    if not lg:
        return ""
    n = max(1, int(n_acct or 0))
    if ko:
        return f"보유 {lg}({n}계좌), 평가 손익 {_pos_usd(pnl)}"
    return f"Holding {lg} ({n} account{'' if n == 1 else 's'}), open P&L {_pos_usd(pnl)}"


def _pos_line_closed(asset, legs, ko) -> str:
    lg = _pos_legs_txt(asset, legs, ko)
    if not lg:
        return ""
    return f"최근 진입 {lg}, 청산됨" if ko else f"Last entry {lg}, closed"


def _pos_line_pending(asset, legs, ko) -> str:
    lg = _pos_legs_txt(asset, legs, ko)
    if not lg:
        return ""
    return f"최근 진입 {lg}, 보유 확인 중" if ko else f"Last entry {lg}, checking position"


# 보유 줄 글자 색(대표 2026-10-29 "회색 말고 색깔 줘"): 이익 초록, 손실 빨강, 그 밖(0, 모름, 확인 중, 청산됨)은 짙은 글자색.
_POS_UP, _POS_DOWN, _POS_INK = "#16a34a", "#dc2626", "#1f2937"


def _pos_color(state, pnl) -> str:
    v = _pos_num(pnl) if state == "hold" else None
    if v is not None and round(v) > 0:
        return _POS_UP
    if v is not None and round(v) < 0:
        return _POS_DOWN
    return _POS_INK


def _pos_acct_tail(key) -> str:
    """계좌 키('projectx:12345872') → '…5872'(체결 DM과 같은 끝 4자리, 영문과 숫자만)."""
    s = "".join(c for c in str(key or "").split(":", 1)[-1] if c.isascii() and c.isalnum())
    return "…" + s[-4:]


def _pos_line_acct(asset, key, legs, pnl, ko) -> str:
    """펼친 계좌별 줄: '…5872  GC 1 + MGC 3계약  +$120'."""
    lg = _pos_legs_txt(asset, legs, ko)
    if not lg:
        return ""
    return f"{_pos_acct_tail(key)}  {lg}  {_pos_usd(pnl)}"


def _pos_rec_clean(asset, v):
    """파일에서 읽은 기록 하나 → 검증된 기록 또는 None. 21p 형식(day, by)은 버린다(계좌, 방향을 몰라 손익을 지어내게 된다)."""
    if not isinstance(v, dict) or not isinstance(v.get("acc"), dict):
        return None
    ts0 = _pos_num(v.get("ts0"))
    if ts0 is None:
        return None
    acc = {}
    for k, legs in v["acc"].items():
        if isinstance(legs, dict):
            lg = {str(r): float(q) for r, q in legs.items() if _pos_num(q) and float(q) > 0}
            if lg:
                acc[str(k)] = lg
    if not acc:
        return None

    def _pxmap(m):
        return {str(r): float(p) for r, p in (m.items() if isinstance(m, dict) else ()) if _pos_num(p) and float(p) > 0}
    side = v.get("side") if v.get("side") in ("LONG", "SHORT", "MIXED") else None
    return {"ts0": ts0, "ts": _pos_num(v.get("ts")) or ts0, "sid": str(v.get("sid") or ""), "side": side, "acc": acc,
            "ref": (_pos_num(v.get("ref")) if (_pos_num(v.get("ref")) or 0) > 0 else None),
            "avg": _pxmap(v.get("avg")),
            "avg_by": {str(k): _pxmap(m) for k, m in (v.get("avg_by") or {}).items() if _pxmap(m)}
            if isinstance(v.get("avg_by"), dict) else {},
            "closed": _pos_num(v.get("closed")), "until": _pos_rec_until(asset, ts0)}


def _load_pos_today() -> dict:
    """{자산: 기록} - 최근 진입 기록(_pos_rec_clean). 못 읽으면 {}."""
    try:
        import json as _json
        with open(_POS_TODAY_PATH, encoding="utf-8") as f:
            d = _json.load(f)
        out = {}
        for k, v in (d.items() if isinstance(d, dict) else ()):
            if k in _ASSET_ENTRIES:
                r = _pos_rec_clean(k, v)
                if r is not None:
                    out[k] = r
        return out
    except Exception:
        return {}


# OKX 50123(2026-11-09 대표 OKX 두 계정 실주문 'This API Key does not have trading permission for the Crypto…'): 키 권한은 켜져 있어도 키의
# 거래 허용 코인 목록(Crypto)에 그 종목의 코인이 없으면 거절된다. 유럽(EEA) 계정의 BTC 무기한은 X-Perp(instType FUTURES)라 Markets의 Expiry도
# 켜야 한다. 안내 문구는 대표 결정(BTC, USDT, USDC, USD 넣기 + 유럽은 Expiry). 일반 '권한' 안내보다 먼저 본다.
_OKX_50123_KO = ("OKX API 키의 거래 허용 코인 목록(Crypto)에 BTC, USDT, USDC, USD를 넣으십시오. 유럽(EEA) 계정은 Markets에서 Expiry도 켜야 "
                 "합니다(유럽 계정의 BTC 무기한은 X-Perp라 OKX가 선물로 분류합니다).")
_OKX_50123_EN = ("Add BTC, USDT, USDC and USD to the OKX API key's allowed crypto list (Crypto). EEA (Europe) accounts also need "
                 "Expiry turned on under Markets (the BTC perpetual on EEA accounts is X-Perp, which OKX classifies as futures).")


def _is_okx_50123(m: str, broker=None) -> bool:
    """OKX 50123인가(최종 리뷰): OKX 오류(브로커가 okx이거나 글에 OKX)의 code= / sCode= 값이 50123일 때만 - 다른 거래소 오류의 숫자
    (주문 번호, 금액 등)에 50123이 들어가도 OKX 안내를 내지 않게."""
    s = str(m or "").lower()
    if broker is not None and str(broker).strip().lower() not in ("", "okx"):
        return False
    if "okx" not in s and str(broker or "").strip().lower() != "okx":
        return False
    import re as _re
    return _re.search(r"\bs?code=50123\b", s) is not None


def _entry_fail_hint(msg: str, ko: bool) -> str:
    """주문 거절 메시지 → 원인별 안내 문구. 10005(권한)를 잔고 문제로 오도하지 않게(대표 2026-07-12)."""
    m = (msg or "").lower()
    if _is_okx_50123(m):
        return _OKX_50123_KO if ko else _OKX_50123_EN
    if "10005" in m or "permission" in m or "40014" in m:
        return ("API 키에 주문 권한이 없습니다. 거래소 API 관리에서 이 키에 파생상품(계약) "
                "주문 권한을 켜고, IP 제한이 있다면 이 컴퓨터 IP를 허용하세요."
                if ko else
                "The API key lacks trade permission. In the exchange's API settings, enable "
                "derivatives (contract) order permission for this key, and allow this computer's "
                "IP if the key is IP-restricted.")
    if "10004" in m or "sign" in m or "40012" in m or "40013" in m:
        return ("API 키/시크릿(패스프레이즈)이 올바른지 다시 확인하세요."
                if ko else "Double-check the API key/secret (and passphrase).")
    if "110007" in m or "insufficient" in m or "margin" in m or "balance" in m or "40754" in m:
        return ("가용 잔고(마진)가 부족합니다 — 잔고를 늘리거나 해당 심볼의 레버리지를 높이세요."
                if ko else
                "Insufficient available margin — add funds or raise the symbol's leverage.")
    return ("잔고(마진), 레버리지, API 키 권한을 확인하세요."
            if ko else "Check margin balance, leverage and API key permissions.")


def _entry_fail_hint_dm(msg: str) -> tuple:
    """주문 거절 → 회원 DM용 원인 안내(KO, EN), 합니다체(2026-10-20). 거래소 원문 오류는 DM에 싣지 않는다(서버 execerr와 같은 규약)."""
    m = (msg or "").lower()
    if _is_okx_50123(m):
        return _OKX_50123_KO, _OKX_50123_EN
    if m.startswith("entry closed:"):                 # Bitget UTA 진입 손절 실패 → 앱이 바로 닫음(2026-11-11 리뷰 P1-3)
        return ("진입은 체결됐지만 손절을 걸지 못해 앱이 그 포지션을 바로 시장가로 닫았습니다. 지금 열린 포지션은 없습니다. "
                "API 키의 거래 권한과 거래소 공지를 확인하십시오.",
                "The entry filled, but the stop could not be placed, so the app closed that position at market right away. "
                "No position is open now. Please check the API key's trade permission and the exchange's announcements.")
    if "10005" in m or "permission" in m or "40014" in m:
        return ("API 키에 주문 권한이 없습니다. 거래소 API 관리에서 이 키에 파생상품(계약) 주문 권한을 켜고, IP 제한이 있다면 "
                "이 컴퓨터 IP를 허용하십시오.",
                "The API key lacks trade permission. In the exchange's API settings, enable derivatives (contract) order "
                "permission for this key, and allow this computer's IP if the key is IP-restricted.")
    if "10004" in m or "sign" in m or "40012" in m or "40013" in m:
        return ("API 키와 시크릿(패스프레이즈)이 맞는지 다시 확인하십시오.", "Please double-check the API key and secret (and passphrase).")
    if "110007" in m or "insufficient" in m or "margin" in m or "balance" in m or "40754" in m:
        return ("가용 잔고(증거금)가 부족합니다. 잔고를 늘리거나 해당 심볼의 레버리지를 높이십시오.",
                "Available margin is insufficient. Please add funds or raise the symbol's leverage.")
    return ("잔고(증거금), 레버리지, API 키 권한을 확인하십시오.", "Please check the margin balance, leverage and API key permissions.")


def _preflight_hint_dm(msg: str, broker=None) -> tuple:
    """진입 전 점검 실패 DM의 원인 안내(KO, EN), 합니다체. NinjaTrader는 거래소 키 안내 대신 NinjaTrader, 애드온 안내(2026-10-20 검토)."""
    m = (msg or "").lower()
    if _is_okx_50123(m, broker):
        return _OKX_50123_KO, _OKX_50123_EN               # 2026-11-09 b: 점검 단계에서도 같은 안내(아래 일반 안내로 넘기기 전에)
    if str(broker or "") == "nt8" or "nt8" in m or "bridge" in m or "애드온" in m or "ninjatrader" in m:
        return ("NinjaTrader가 켜져 있고 EQ Autopilot 애드온이 연결돼 있는지 확인하십시오.",
                "Please check that NinjaTrader is running and the EQ Autopilot add-on is connected.")
    return _entry_fail_hint_dm(msg)


def _ntr_why_text(code, ko) -> str:
    """서버 NO TRADE 사유 코드(no_trade_reason) → 로그 한 줄(KO 또는 EN)."""
    c = str(code or "").strip()
    if c == "app_update_needed":
        return ("사유: 이 토큰으로 최근 7일 안에 켜진 PC 가운데 옛 버전 앱이 있어 서버가 이 금 진입을 보내지 않았습니다. 그 PC도 이 버전으로 "
                "업데이트하십시오. 그 PC를 더 쓰지 않으면 마지막으로 켠 날부터 7일 뒤에 풀립니다." if ko else
                "Reason: a PC on this token seen in the last 7 days runs an old app version, so the server did not send this gold "
                "entry. Please update that PC too. If that PC is no longer used, this clears 7 days after it was last on.")
    return (f"사유(서버): {c}" if ko else f"Reason (server): {c}")


# Bitget 통합 거래 계정(UTA) 지원은 테스트 중(대표 2026-11-11) - UTA로 판별된 키의 연결 테스트, 라이브 시작에 늘 한 줄. 클래식 키에는 보이지 않는다.
# 대표 2026-11-11: 테스트 중인 기능의 오류는 보상하지 않는다(약관상 책임은 그대로 - 약관 §20이 '손절 없이 체결된 진입'을 결함으로 든다).
_BG_UTA_TESTING_KO = "Bitget 통합 계정: 테스트 중인 지원입니다. 이 기능의 오류는 보상(한 달 무료, 할인 쿠폰) 대상이 아닙니다(약관상 책임은 그대로)."
_BG_UTA_TESTING_EN = ("Bitget unified account: support is in testing. Errors in this feature are not eligible for compensation (a free "
                      "month or a discount coupon); our liability under the Terms is unchanged.")


def _bg_is_uta(b) -> bool:
    """Bitget 어댑터가 이 키를 통합 거래 계정(UTA)으로 판별했나(묻지 않는다 - 기억만 읽는다)."""
    try:
        return str(getattr(b, "name", "") or "") == "bitget" and b.account_type() == "uta"
    except Exception:
        return False


def _not_sent_why_dm(msg: str) -> tuple:
    """'not sent:' 진입(주문이 앱을 떠나지 않음)의 회원 DM 이유(KO, EN), 합니다체(최종 리뷰). 거래소 원문은 싣지 않는다."""
    m = str(msg or "").lower()
    if "changing between classic" in m or "unified trading account" in m:
        return ("Bitget 계정이 클래식과 통합 거래 계정 사이에서 바뀌는 중이었습니다. 바꾸기가 끝나면 다음 신호부터 진입합니다.",
                "The Bitget account was switching between Classic and Unified Trading Account. Once the switch is done, the "
                "app enters from the next signal.")
    if "instrument spec unavailable" in m:
        return ("OKX에서 종목 정보를 받지 못했습니다. 다음 신호에 다시 시도합니다.",
                "The app could not get the instrument details from OKX. It tries again on the next signal.")
    return ("다음 신호에 다시 시도합니다.", "The app tries again on the next signal.")


def _entry_err_unknown(msg: str) -> bool:
    """크립토 진입 오류가 '거래소가 주문을 받았는지 모르는' 종류인가(오픈 준비 버그 조사 2026-10-06 B).

    Bybit·Bitget 어댑터는 주문 POST 예외를 전부 {"error": str(e)}로 돌려줘, 응답만 잃은 타임아웃·연결
    끊김·5xx도 '진입 주문이 거절되었습니다'로 보고됐다 - 주문이 들어갔다면 손절이 붙은 포지션이 열려 있다.
    거래소가 처리하고 답한 거절(retCode=, failed: code=, HTTP 4xx)과 앱 쪽 입력 오류만 거절로 보고,
    그 밖은 모른다고 본다(모르는 오류를 '거절'로 말하는 쪽이 회원의 수동 재진입·이중 노출로 이어진다)."""
    import re as _re
    m = str(msg or "")
    if "retCode=" in m or "failed: code=" in m:
        return False
    if _re.search(r"HTTP 4\d\d\b|\b4\d\d Client Error", m):
        return False
    # "not sent:" = 어댑터가 보내기 전에 멈춘 것(2026-11-11 Bitget 계정 유형이 바뀌는 중 등) - 주문은 나가지 않았다.
    # "entry closed:" = 진입 직후 손절을 걸지 못해 어댑터가 그 포지션을 바로 시장가로 닫았다(Bitget UTA, 리뷰 P1-3) - 남은 포지션 없음.
    # "not filled:" = 시장가 주문이 체결 없이 끝났다(거래소가 확인해 준 결과) - 포지션 없음.
    if m.startswith(("invalid side", "qty<=0", "not sent:", "entry closed:", "not filled:")):
        return False
    return True


def _cross_basis_bitget() -> float:
    """빗겟 캘리브레이션(대표 2026-07-12): 신호 손절은 Bybit BTCUSDT.P 좌표계 —
    Bitget 체결용으로 순수 거래소 베이시스(빗겟가-바이빗가, 같은 순간 공개 티커)만 가산한다.
    (진입 후 드리프트는 양쪽 공통이라 미반영 — Bybit 회원의 원본 손절/공식 채점과 일관 유지.)
    실패 시 0.0(원본 손절 그대로) — 베이시스는 보통 리스크의 2~4%라 미조정도 치명적이지 않다."""
    import requests
    try:
        by = requests.get("https://api.bybit.com/v5/market/tickers",
                          params={"category": "linear", "symbol": "BTCUSDT"}, timeout=5).json()
        bg = requests.get("https://api.bitget.com/api/v2/mix/market/ticker",
                          params={"productType": "USDT-FUTURES", "symbol": "BTCUSDT"}, timeout=5).json()
        p_by = float(by["result"]["list"][0]["lastPrice"])
        p_bg = float(bg["data"][0]["lastPr"])
        return p_bg - p_by
    except Exception:
        return 0.0


def _cross_basis_okx(base: str = "https://www.okx.com", inst: str = "BTC-USDT-SWAP") -> float:
    """OKX 캘리브레이션(2026-11-03, 빗겟과 같은 원칙): 신호 손절은 Bybit BTCUSDT.P 좌표계라 OKX 체결용으로
    순수 거래소 베이시스(OKX 체결 종목 최종가 - 바이빗가, 같은 순간 공개 티커)만 더한다.
    base = 회원 키가 사는 OKX 지역 주소, inst = 그 계정이 거래하는 종목(어댑터가 고른 것 - 유럽 계정은 X-Perp, 2026-11-05).
    공개 시세라 키를 보내지 않는다. 실패 시 0.0(원본 손절 그대로)."""
    import requests
    try:
        by = requests.get("https://api.bybit.com/v5/market/tickers",
                          params={"category": "linear", "symbol": "BTCUSDT"}, timeout=5).json()
        ok = requests.get(f"{base}/api/v5/market/ticker",
                          params={"instId": inst or "BTC-USDT-SWAP"}, timeout=5).json()
        p_by = float(by["result"]["list"][0]["lastPrice"])
        p_ok = float(ok["data"][0]["last"])
        return p_ok - p_by
    except Exception:
        return 0.0


def _cross_basis_for(broker, b=None) -> float:
    """체결 거래소가 Bybit가 아니면 그 거래소 베이시스(Bitget·OKX), Bybit·그 밖은 0.0. 진입·지정가 두 자리가 같이 쓴다."""
    if broker == "bitget":
        return _cross_basis_bitget()
    if broker == "okx":
        try:
            _inst = b._inst_of("BTCUSDT") if b is not None else "BTC-USDT-SWAP"   # 캐시된 종목(연결 때 정함) - 진입 앞 조회 없음
        except Exception:
            _inst = "BTC-USDT-SWAP"
        return _cross_basis_okx(str(getattr(b, "base", "") or "https://www.okx.com"), _inst)
    return 0.0


